struct  ImGuiInputTextState\
{\
    ImGuiContext*           Ctx;\
    ImStbTexteditState*     Stb;\
    ImGuiInputTextFlags     Flags;\
    ImGuiID                 ID;\
    int                     TextLen;\
    const char*             TextSrc;\
    ImVector<char>          TextA;\
    ImVector<char>          TextToRevertTo;\
    ImVector<char>          CallbackTextBackup;\
    int                     BufCapacity;\
    ImVec2                  Scroll;\
    int                     LineCount;\
    float                   WrapWidth;\
    float                   CursorAnim;\
    bool                    CursorFollow;\
    bool                    CursorCenterY;\
    bool                    SelectedAllMouseLock;\
    bool                    EditedBefore;\
    bool                    EditedThisFrame;\
    bool                    ValidatedThisFrame;\
    bool                    WantReloadUserBuf;\
    ImS8                    LastMoveDirectionLR;\
    int                     ReloadSelectionStart;\
    int                     ReloadSelectionEnd;\
    ImGuiInputTextState();\
    ~ImGuiInputTextState();\
    void        ClearText()                 { TextLen = 0; TextA[0] = 0; CursorClamp(); }\
    void        ClearFreeMemory()           { TextA.clear(); TextToRevertTo.clear(); }\
    void        OnKeyPressed(int key);\
    void        OnCharPressed(unsigned int c);\
    float       GetPreferredOffsetX() const;\
    const char* GetText()                   { return TextA.Data ? TextA.Data : \"\"; }\
    void        CursorAnimReset();\
    void        CursorClamp();\
    bool        HasSelection() const;\
    void        ClearSelection();\
    int         GetCursorPos() const;\
    int         GetSelectionStart() const;\
    int         GetSelectionEnd() const;\
    void        SetSelection(int start, int end);\
    void        SelectAll();\
    void        ReloadUserBufAndSelectAll();\
    void        ReloadUserBufAndKeepSelection();\
    void        ReloadUserBufAndMoveToEnd();\
};",
    locat="imgui_internal:1349",
    name="ImGuiInputTextState",
    re_name="struct_re"},
