    item="\
struct ImGuiContext\
{\
    bool                    Initialized;\
    bool                    WithinFrameScope;\
    bool                    WithinFrameScopeWithImplicitWindow;\
    bool                    TestEngineHookItems;\
    int                     FrameCount;\
    int                     FrameCountEnded;\
    int                     FrameCountPlatformEnded;\
    int                     FrameCountRendered;\
    double                  Time;\
