    ImGuiStyle              Style;\
    ImGuiConfigFlags        ConfigFlagsCurrFrame;\
    ImGuiConfigFlags        ConfigFlagsLastFrame;\
    ImVector<ImFontAtlas*>  FontAtlases;\
