    item="\
struct  ImGuiWindow\
{\
    ImGuiContext*           Ctx;\
    char*                   Name;\
    ImGuiID                 ID;\
    ImGuiWindowFlags        Flags, FlagsPreviousFrame;\
    ImGuiChildFlags         ChildFlags;\
    ImGuiWindowClass        WindowClass;\
    ImGuiViewportP*         Viewport;\
    ImGuiID                 ViewportId;\
    ImVec2                  ViewportPos;\
    int                     ViewportAllowPlatformMonitorExtend;\
    ImVec2                  Pos;\
    ImVec2                  Size;\
    ImVec2                  SizeFull;\
    ImVec2                  ContentSize;\
    ImVec2                  ContentSizeIdeal;\
    ImVec2                  ContentSizeExplicit;\
    ImVec2                  WindowPadding;\
    float                   WindowRounding;\
    float                   WindowBorderSize;\
    float                   TitleBarHeight, MenuBarHeight;\
    float                   DecoOuterSizeX1, DecoOuterSizeY1;\
    float                   DecoOuterSizeX2, DecoOuterSizeY2;\
    float                   DecoInnerSizeX1, DecoInnerSizeY1;\
    int                     NameBufLen;\
    ImGuiID                 MoveId;\
    ImGuiID                 TabId;\
    ImGuiID                 ChildId;\
    ImGuiID                 PopupId;\
    ImVec2                  Scroll;\
    ImVec2                  ScrollMax;\
    ImVec2                  ScrollTarget;\
    ImVec2                  ScrollTargetCenterRatio;\
    ImVec2                  ScrollTargetEdgeSnapDist;\
    ImVec2                  ScrollbarSizes;\
    bool                    ScrollbarX, ScrollbarY;\
    bool                    ScrollbarXStabilizeEnabled;\
    ImU8                    ScrollbarXStabilizeToggledHistory;\
    bool                    ViewportOwned;\
    bool                    Active;\
    bool                    WasActive;\
    bool                    WriteAccessed;\
    bool                    Collapsed;\
    bool                    WantCollapseToggle;\
    bool                    SkipItems;\
    bool                    SkipRefresh;\
    bool                    Appearing;\
    bool                    Hidden;\
    bool                    IsFallbackWindow;\
    bool                    IsExplicitChild;\
    bool                    HasCloseButton;\
    signed char             ResizeBorderHovered;\
    signed char             ResizeBorderHeld;\
    short                   BeginCount;\
    short                   BeginCountPreviousFrame;\
    short                   BeginOrderWithinParent;\
    short                   BeginOrderWithinContext;\
    short                   FocusOrder;\
    ImGuiDir                AutoPosLastDirection;\
    ImS8                    AutoFitFramesX, AutoFitFramesY;\
    bool                    AutoFitOnlyGrows;\
    ImS8                    HiddenFramesCanSkipItems;\
    ImS8                    HiddenFramesCannotSkipItems;\
    ImS8                    HiddenFramesForRenderOnly;\
    ImS8                    DisableInputsFrames;\
    ImGuiWindowBgClickFlags BgClickFlags : 8;\
    ImGuiCond               SetWindowPosAllowFlags : 8;\
    ImGuiCond               SetWindowSizeAllowFlags : 8;\
    ImGuiCond               SetWindowCollapsedAllowFlags : 8;\
    ImGuiCond               SetWindowDockAllowFlags : 8;\
    ImVec2                  SetWindowPosVal;\
    ImVec2                  SetWindowPosPivot;\
    ImVector<ImGuiID>       IDStack;\
    ImGuiWindowTempData     DC;\
    ImRect                  OuterRectClipped;\
    ImRect                  InnerRect;\
    ImRect                  InnerClipRect;\
    ImRect                  WorkRect;\
    ImRect                  ParentWorkRect;\
    ImRect                  ClipRect;\
    ImRect                  ContentRegionRect;\
    ImVec2ih                HitTestHoleSize;\
    ImVec2ih                HitTestHoleOffset;\
    int                     LastFrameActive;\
    int                     LastFrameJustFocused;\
    float                   LastTimeActive;\
    ImGuiStorage            StateStorage;\
    ImVector<ImGuiOldColumns> ColumnsStorage;\
    float                   FontWindowScale;\
    float                   FontWindowScaleParents;\
    float                   FontRefSize;\
    int                     SettingsOffset;\
    ImDrawList*             DrawList;\
    ImDrawList              DrawListInst;\
    ImGuiWindow*            ParentWindow;\
    ImGuiWindow*            ParentWindowInBeginStack;\
    ImGuiWindow*            RootWindow;\
    ImGuiWindow*            RootWindowPopupTree;\
    ImGuiWindow*            RootWindowDockTree;\
    ImGuiWindow*            RootWindowForTitleBarHighlight;\
    ImGuiWindow*            RootWindowForNav;\
    ImGuiWindow*            ParentWindowForFocusRoute;\
    ImGuiWindow*            NavLastChildNavWindow;\
    ImGuiID                 NavLastIds[ImGuiNavLayer_COUNT];\
    ImRect                  NavRectRel[ImGuiNavLayer_COUNT];\
    ImVec2                  NavPreferredScoringPosRel[ImGuiNavLayer_COUNT];\
    ImGuiID                 NavRootFocusScopeId;\
    int                     MemoryDrawListIdxCapacity;\
    int                     MemoryDrawListVtxCapacity;\
    bool                    MemoryCompacted;\
    bool                    DockIsActive        :1;\
    bool                    DockNodeIsVisible   :1;\
    bool                    DockTabIsVisible    :1;\
    bool                    DockTabWantClose    :1;\
    short                   DockOrder;\
    ImGuiWindowDockStyle    DockStyle;\
    ImGuiDockNode*          DockNode;\
    ImGuiDockNode*          DockNodeAsHost;\
    ImGuiID                 DockId;\
    bool                    InheritNoInputs;\
public:\
    ImGuiWindow(ImGuiContext* context, const char* name);\
    ~ImGuiWindow();\
    ImGuiID     GetID(const char* str, const char* str_end = ((void *)0));\
    ImGuiID     GetID(const void* ptr);\
    ImGuiID     GetID(int n);\
    ImGuiID     GetIDFromPos(const ImVec2& p_abs);\
    ImGuiID     GetIDFromRectangle(const ImRect& r_abs);\
    ImRect      Rect() const            { return ImRect(Pos.x, Pos.y, Pos.x + Size.x, Pos.y + Size.y); }\
    ImRect      TitleBarRect() const    { return ImRect(Pos, ImVec2(Pos.x + SizeFull.x, Pos.y + TitleBarHeight)); }\
    ImRect      MenuBarRect() const     { float y1 = Pos.y + TitleBarHeight; return ImRect(Pos.x, y1, Pos.x + SizeFull.x, y1 + MenuBarHeight); }\
};",
